import React, { useState, useEffect } from 'react';
import { supabase } from './supabaseClient';
import DepartmentCard from './components/DepartmentCard';
import ScheduleCalendar from './components/ScheduleCalendar';
import ConflictTable from './components/ConflictTable';
import GlobalResourceMonitor from './components/GlobalResourceMonitor';
import {
  LayoutDashboard, Printer, Activity, Zap, LogOut, Lock, User, RefreshCw
} from 'lucide-react';

function App() {
  const [session, setSession] = useState(null);
  const [loading, setLoading] = useState(true);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [departments, setDepartments] = useState([]);
  const [globalSchedule, setGlobalSchedule] = useState([]);
  const [allExamDates, setAllExamDates] = useState([]);

  // --- AUTH ---
  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      setSession(session);
      if (session) fetchAllData();
      setLoading(false);
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
      if (session) fetchAllData();
      else {
        setDepartments([]);
        setGlobalSchedule([]);
      }
    });

    return () => subscription.unsubscribe();
  }, []);

  // --- FETCH DATA ---
  const fetchAllData = async () => {
    setLoading(true);
    try {
      const [deptsRes, schedsRes] = await Promise.all([
        supabase.from('departments').select('*').order('name', { ascending: true }),
        supabase.from('schedules').select('*')
      ]);

      if (deptsRes.data) setDepartments(deptsRes.data);
      if (schedsRes.data) {
        const sortedData = schedsRes.data.sort((a, b) => a.id - b.id);
        const dates = [...new Set(sortedData.map(s => s.exam_date))].sort();
        setGlobalSchedule(runConflictDetection(sortedData));
        setAllExamDates(dates);
      }
    } catch (err) {
      console.error("Cloud Sync Error:", err);
    } finally {
      setLoading(false);
    }
  };

  // ─────────────────────────────────────────────────────────────
  // FIXED: COMPREHENSIVE CRUD & SYNC HANDLER (UPSERT ENABLED)
  // ─────────────────────────────────────────────────────────────
  const handleDepartmentUpdate = async (actionType, payload) => {
    console.log(`Syncing ${actionType}...`, payload);

    // PATH 1: SCHEDULE DATA (Handles both existing updates and new Lock & Save drafts)
    if (['manual_override', 'lock_and_save', 'schedule_sync'].includes(actionType)) {
      if (!Array.isArray(payload) || payload.length === 0) return false;

      // Filter payload to ensure data integrity before sending to Supabase
      const dataToSync = payload.map(item => {
        // We strip frontend-only helpers like 'hasConflict' and 'tempId' 
        // to prevent PostgreSQL "column does not exist" errors.
        const { hasConflict, conflictType, tempId, ...validData } = item;
        return {
          ...validData,
          year_level: String(validData.year_level),
          flagged: Boolean(validData.flagged ?? false),
          isManualProctor: Boolean(validData.isManualProctor ?? false)
        };
      });

      // USE UPSERT: This is the key fix. It handles new items (no ID) and updates (with ID)
      const { error } = await supabase
        .from('schedules')
        .upsert(dataToSync, { onConflict: 'id' });

      if (error) {
        console.error(`❌ Sync Error [${actionType}]:`, error.message);
        return false;
      }

      await fetchAllData();
      return true;
    }

    // PATH 2: DEPARTMENT METADATA (Proctors, Rooms, Subjects lists)
    if (['proctors', 'rooms', 'subjects'].includes(actionType)) {
      if (!payload || !payload.id) return false;

      const { id } = payload;
      const newValue = payload[actionType];

      const { error } = await supabase
        .from('departments')
        .update({ [actionType]: newValue })
        .eq('id', id);

      if (error) {
        console.error(`❌ Metadata Update Error [${actionType}]:`, error.message);
        return false;
      }

      setDepartments(prev => prev.map(d => d.id === id ? { ...d, [actionType]: newValue } : d));
      return true;
    }

    return true;
  };

  // --- GENERATION ---
  // FIXED: Added 'await' to delete and improved data integrity
  const handleScheduleGenerated = async (newAssignments, _newDates, deptCode) => {
    if (!newAssignments?.length) return;
    const targetYear = String(newAssignments[0].year_level);

    try {
      // 1. FORCE the delete to finish before moving on
      const { error: deleteError } = await supabase.from('schedules')
        .delete()
        .eq('dept_code', deptCode)
        .eq('year_level', targetYear);

      if (deleteError) throw deleteError;

      // 2. Format data for clean insert
      const formattedData = newAssignments.map(item => ({
        dept_code: deptCode,
        year_level: String(item.year_level),
        section: item.section || 'A',
        subject_code: item.subject_code || 'N/A',
        subject_name: item.subject_name || 'N/A',
        proctor: item.proctor,
        room: item.room,
        exam_date: item.exam_date,
        start_time: item.start_time,
        end_time: item.end_time,
        flagged: false,
        flagNote: "",
        isManualProctor: false
      }));

      // 3. Insert and wait for completion
      const { error: insertError } = await supabase.from('schedules').insert(formattedData);
      if (insertError) throw insertError;

      // 4. Final sync to UI
      await fetchAllData();

    } catch (err) {
      console.error("Critical Generation Error:", err.message);
      alert("Failed to save generated schedule. Please try again.");
    }
  };

  // --- CONFLICT DETECTION ---
  // FIXED: Added section check to prevent self-conflicts within the same class block
  const runConflictDetection = (scheduleList) => {
    return scheduleList.map(item => {
      const conflict = scheduleList.find(target =>
        // Must be a different record
        target.id !== item.id &&
        // Must be on the same day
        target.exam_date === item.exam_date &&
        // IMPORTANT: Must be a DIFFERENT section (Ignore subjects in the same class)
        target.section !== item.section &&
        // Must share a Resource (Room or Proctor)
        (target.room === item.room || target.proctor === item.proctor) &&
        // Must have a Time Overlap
        (item.start_time < target.end_time && item.end_time > target.start_time)
      );

      return {
        ...item,
        hasConflict: !!conflict,
        conflictType: conflict ? (conflict.room === item.room ? 'ROOM' : 'PROCTOR') : null
      };
    });
  };

  // --- UI HANDLERS ---
  const addDepartment = async () => {
    const name = prompt("Enter Department Name:");
    const code = prompt("Enter Dept Code (e.g. CCS):");
    if (name && code) {
      const { data, error } = await supabase.from('departments').insert([{
        name,
        code: code.toUpperCase(),
        subjects: { 1: [], 2: [], 3: [], 4: [], 5: [] },
        proctors: [],
        rooms: []
      }]).select();
      if (!error) setDepartments(prev => [...prev, data[0]]);
    }
  };

  const deleteDepartment = async (deptId, deptCode) => {
    if (window.confirm(`Delete ${deptCode} permanently?`)) {
      await supabase.from('departments').delete().eq('id', deptId);
      setDepartments(prev => prev.filter(d => d.id !== deptId));
      setGlobalSchedule(prev => prev.filter(item => item.dept_code !== deptCode));
    }
  };

  const handleSignIn = async () => {
    const { error } = await supabase.auth.signInWithPassword({ email, password });
    if (error) alert(error.message);
  };

  const handleSignUp = async () => {
    const { error } = await supabase.auth.signUp({ email, password });
    if (error) alert(error.message ? error.message : "Check email for confirmation!");
  };

  if (!session) {
    return (
      <div className="min-h-screen bg-slate-900 flex items-center justify-center p-6">
        <div className="bg-white w-full max-w-md rounded-[3.5rem] p-12 shadow-2xl">
          <div className="text-center mb-10">
            <div className="inline-flex bg-blue-600 p-5 rounded-[2rem] mb-6 text-white shadow-xl">
              <Lock size={32} />
            </div>
            <h1 className="text-3xl font-black uppercase italic tracking-tighter">Accord <span className="text-blue-600">Pro</span></h1>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-2">Institutional Workspace</p>
          </div>
          <div className="space-y-4">
            <div className="relative">
              <User className="absolute left-5 top-5 text-slate-300" size={18} />
              <input type="email" placeholder="Email" value={email} onChange={e => setEmail(e.target.value)} className="w-full bg-slate-50 p-5 pl-14 rounded-2xl font-black text-xs border-2 border-slate-50 outline-none focus:border-blue-500" />
            </div>
            <div className="relative">
              <Lock className="absolute left-5 top-5 text-slate-300" size={18} />
              <input type="password" placeholder="Password" value={password} onChange={e => setPassword(e.target.value)} className="w-full bg-slate-50 p-5 pl-14 rounded-2xl font-black text-xs border-2 border-slate-50 outline-none focus:border-blue-500" />
            </div>
            <button onClick={handleSignIn} className="w-full bg-slate-900 text-white p-5 rounded-2xl font-black uppercase text-[10px] tracking-widest shadow-xl active:scale-95">Sign In</button>
            <button onClick={handleSignUp} className="w-full text-slate-400 p-2 font-black uppercase text-[9px] hover:text-blue-600">Register</button>
          </div>
        </div>
      </div>
    );
  }

  const conflictCount = globalSchedule.filter(s => s.hasConflict).length;

  return (
    <div className="min-h-screen bg-slate-50 pb-24 font-sans text-slate-900">
      <nav className="bg-slate-900 px-8 py-5 mb-10 flex justify-between items-center sticky top-0 z-50 shadow-2xl text-white">
        <div className="flex items-center gap-3 font-black uppercase tracking-tighter text-xl">
          <LayoutDashboard size={28} className="text-blue-500" />
          ACCORD <span className="text-blue-500 italic">PRO</span>
        </div>
        <div className="flex items-center gap-6">
          <div className={`px-5 py-2 rounded-2xl border-2 flex items-center gap-2 text-[10px] font-black uppercase transition-all ${conflictCount > 0 ? 'bg-rose-500/10 border-rose-500/50 text-rose-500' : 'bg-emerald-500/10 border-emerald-500/50 text-emerald-500'}`}>
            <Activity size={14} className={conflictCount > 0 ? 'animate-pulse' : ''} />
            {conflictCount > 0 ? `${conflictCount} Conflicts` : 'Sync Active'}
          </div>
          <button onClick={addDepartment} className="bg-blue-600 hover:bg-blue-500 text-white px-6 py-2.5 rounded-2xl font-black text-[10px] uppercase shadow-lg transition-all active:scale-95">Add Dept</button>
          <button onClick={() => supabase.auth.signOut()} className="bg-white/10 hover:bg-rose-500 text-white p-2.5 rounded-xl transition-all">
            <LogOut size={18} />
          </button>
        </div>
      </nav>

      <main className="container mx-auto px-6 max-w-7xl">
        {loading ? (
          <div className="flex flex-col items-center justify-center py-40">
            <RefreshCw size={48} className="text-blue-500 animate-spin mb-4" />
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">Syncing Cloud Database...</p>
          </div>
        ) : (
          <>
            <div className="grid grid-cols-1 gap-12 mb-16">
              <ConflictTable schedule={globalSchedule} />
              <GlobalResourceMonitor allDepartments={departments} globalSchedule={globalSchedule} />
            </div>

            <div className="space-y-16">
              {departments.map((dept) => (
                <DepartmentCard
                  key={dept.id}
                  dept={dept}
                  allDepartments={departments}
                  onUpdate={handleDepartmentUpdate}
                  onDeleteDept={deleteDepartment}
                onClearSchedule={async (dCode, yLevel) => {
  if (window.confirm(`Delete all Year ${yLevel} schedules for ${dCode}?`)) {
    const { error } = await supabase
      .from('schedules')
      .delete()
      .eq('dept_code', dCode)
      .eq('year_level', String(yLevel)); // Ensure it's a string to match DB type

    if (error) {
      console.error("Delete Error:", error.message);
    } else {
      await fetchAllData(); // Refresh the global view immediately
    }
  }
} }
                  globalSchedule={globalSchedule}
                  onGenerate={(schedule, dates) => handleScheduleGenerated(schedule, dates, dept.code)}
                />
              ))}
            </div>

            <div className="mt-32 pt-24 border-t-4 border-slate-900/5">
              <div className="flex justify-between items-end mb-12 px-6">
                <h2 className="text-6xl font-black text-slate-900 tracking-tighter">Master <span className="text-blue-600 italic">Timeline</span></h2>
                <button onClick={() => window.print()} className="bg-slate-900 text-white px-10 py-5 rounded-[2.5rem] font-black text-[10px] uppercase tracking-widest flex items-center gap-3 shadow-2xl active:scale-95 transition-all">
                  <Printer size={20} /> Export Master PDF
                </button>
              </div>
              <div className="bg-white p-4 rounded-[4rem] shadow-xl border border-slate-100">
                {globalSchedule.length > 0 ? (
                  <ScheduleCalendar scheduleData={globalSchedule} examDates={allExamDates} />
                ) : (
                  <div className="py-32 text-center text-slate-300 font-black uppercase tracking-[0.5em] text-sm">
                    <Zap size={48} className="mx-auto mb-4 opacity-20" /> Database Empty
                  </div>
                )}
              </div>
            </div>
          </>
        )}
      </main>
    </div>
  );
}

export default App;
